const { withAndroidColors, AndroidConfig } = require("expo/config-plugins");

/**
 * Root-cause fix for the mobile theme not matching the Kisan4U
 * white-and-green palette in a BUILT APK even after `theme.ts`/`app.json`
 * were corrected: `apps/mobile/android` is a gitignored, generated native
 * project (created once by `expo prebuild`, never auto-regenerated by
 * `expo run:android` once it already exists on disk — see the final
 * report for the full investigation). Two native Android resources were
 * never derived from ANY app.json key at all and were still the stock
 * React Native template defaults:
 *   - colorPrimary: #023c69 (a template navy blue, tints native chrome
 *     RN itself doesn't theme — EditText cursor/selection handles, some
 *     system ripple/accent colors)
 *   - activityBackground: #F4F7F3 (a one-shade-off drift from
 *     theme.ts's Colors.light.background, #F6F8F5)
 *
 * app.json has no config key for either of these — they only exist as
 * raw native XML, so the only way to make them survive a FRESH `expo
 * prebuild` (required to actually pick up any app.json/theme change,
 * since the existing android/ directory is otherwise reused as-is) is a
 * config plugin that patches them after prebuild generates the file.
 * Keep these two hex values in sync with
 * apps/mobile/src/constants/theme.ts's Colors.light.green700/background
 * by eye, the same convention that file's own doc comment already
 * follows for its own sync with packages/ui/src/styles/tokens.css.
 */
const GREEN_700 = "#2B6B3D";
const BACKGROUND = "#F6F8F5";

module.exports = function withKisan4uAndroidColors(config) {
  return withAndroidColors(config, (config) => {
    config.modResults = AndroidConfig.Colors.assignColorValue(config.modResults, {
      name: "colorPrimary",
      value: GREEN_700,
    });
    config.modResults = AndroidConfig.Colors.assignColorValue(config.modResults, {
      name: "activityBackground",
      value: BACKGROUND,
    });
    return config;
  });
};
